{
  "$schema": "https://opencode.ai/config.json",
  "model": "oceans-llm/claude-sonnet-4.6",
  "provider": {
    "oceans-llm": {
      "models": {
        "claude-sonnet-4.6": {
          "attachment": true,
          "cost": {
            "cache_read": 0.33,
            "input": 3.3,
            "output": 16.5
          },
          "limit": {
            "context": 200000,
            "output": 128000
          },
          "name": "Claude Sonnet on AWS Bedrock",
          "reasoning": true,
          "tool_call": true,
          "variants": {
            "high": {
              "reasoningEffort": "high"
            },
            "max": {
              "reasoningEffort": "xhigh"
            }
          }
        }
      },
      "name": "oceans-llm",
      "npm": "@ai-sdk/anthropic",
      "options": {
        "apiKey": "{env:OCEANS_LLM_API_KEY}",
        "baseURL": "http://127.0.0.1:3000"
      }
    }
  }
}

{
  "providers": {
    "oceans-llm": {
      "api": "anthropic-messages",
      "apiKey": "$OCEANS_LLM_API_KEY",
      "baseUrl": "http://127.0.0.1:3000",
      "compat": {
        "forceAdaptiveThinking": true
      },
      "models": [
        {
          "contextWindow": 200000,
          "cost": {
            "cacheRead": 0.33,
            "cacheWrite": 4.125,
            "input": 3.3,
            "output": 16.5
          },
          "id": "claude-sonnet-4.6",
          "input": [
            "text",
            "image"
          ],
          "maxTokens": 128000,
          "name": "Claude Sonnet on AWS Bedrock",
          "reasoning": true,
          "thinkingLevelMap": {
            "high": "high",
            "low": "low",
            "max": "max",
            "medium": "medium",
            "minimal": null,
            "off": null,
            "xhigh": "xhigh"
          }
        }
      ]
    }
  }
}

